-- Normalize the recovered company supply-chain source without forcing it
-- into the incompatible legacy 20-row company_products_master generation.

CREATE TABLE public.company_product_rules_master (
  rule_id bigint PRIMARY KEY,
  type_id bigint NOT NULL REFERENCES public.company_types_master(type_id),
  tier integer NOT NULL,
  relation_type text NOT NULL,
  product_name text NOT NULL,
  clean_ratio numeric,
  semantics_status text NOT NULL,
  source_jsonb jsonb NOT NULL,
  CONSTRAINT company_product_rules_tier_check CHECK (tier BETWEEN 1 AND 3),
  CONSTRAINT company_product_rules_relation_check CHECK (relation_type IN (
    'tier1_main_output','tier1_byproduct','tier2_required_input',
    'tier2_processed_output','tier3_sale_input'
  )),
  CONSTRAINT company_product_rules_name_nonempty CHECK (btrim(product_name) <> ''),
  CONSTRAINT company_product_rules_ratio_check CHECK (
    (relation_type = 'tier3_sale_input' AND clean_ratio IS NOT NULL AND clean_ratio > 0)
    OR
    (relation_type <> 'tier3_sale_input' AND clean_ratio IS NULL)
  ),
  CONSTRAINT company_product_rules_semantics_check CHECK (
    semantics_status = 'source_catalog_only'
  ),
  CONSTRAINT company_product_rules_source_object CHECK (
    jsonb_typeof(source_jsonb) = 'object'
  )
);

CREATE UNIQUE INDEX company_product_rules_unique_idx
  ON public.company_product_rules_master (type_id, relation_type, product_name);

CREATE INDEX company_product_rules_product_name_idx
  ON public.company_product_rules_master (product_name);

ALTER TABLE public.company_product_rules_master ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.company_product_rules_master FROM anon, authenticated;

