CREATE TABLE public.company_affiliations_master (
  affiliation_id bigint PRIMARY KEY,
  type_id bigint NOT NULL REFERENCES public.company_types_master(type_id),
  direction text NOT NULL,
  source_ordinal integer NOT NULL,
  related_company_name text NOT NULL,
  related_type_id bigint REFERENCES public.company_types_master(type_id),
  resolution_status text NOT NULL,
  source_jsonb jsonb NOT NULL,
  CONSTRAINT company_affiliations_direction_check CHECK (direction IN ('input','output')),
  CONSTRAINT company_affiliations_ordinal_positive CHECK (source_ordinal > 0),
  CONSTRAINT company_affiliations_name_nonempty CHECK (btrim(related_company_name) <> ''),
  CONSTRAINT company_affiliations_resolution_check CHECK (
    (resolution_status = 'exact' AND related_type_id IS NOT NULL)
    OR
    (resolution_status = 'unresolved_name_conflict' AND related_type_id IS NULL)
  ),
  CONSTRAINT company_affiliations_source_object CHECK (
    jsonb_typeof(source_jsonb) = 'object'
  )
);

CREATE UNIQUE INDEX company_affiliations_source_position_unique_idx
  ON public.company_affiliations_master (type_id, direction, source_ordinal);

CREATE INDEX company_affiliations_related_name_idx
  ON public.company_affiliations_master (related_company_name);

CREATE INDEX company_affiliations_related_type_idx
  ON public.company_affiliations_master (related_type_id)
  WHERE related_type_id IS NOT NULL;

ALTER TABLE public.company_affiliations_master ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.company_affiliations_master FROM anon, authenticated;

