CREATE TABLE public.company_upgrades_master (
  upgrade_id bigint PRIMARY KEY,
  type_id bigint NOT NULL UNIQUE REFERENCES public.company_types_master(type_id),
  upgrade_key text NOT NULL,
  cost numeric NOT NULL,
  upkeep_increase numeric NOT NULL,
  bonus_key text NOT NULL,
  bonus_value numeric NOT NULL,
  semantics_status text NOT NULL,
  source_jsonb jsonb NOT NULL,
  CONSTRAINT company_upgrades_key_nonempty CHECK (btrim(upgrade_key) <> ''),
  CONSTRAINT company_upgrades_cost_nonnegative_integer CHECK (
    cost >= 0 AND cost = trunc(cost)
  ),
  CONSTRAINT company_upgrades_upkeep_nonnegative_integer CHECK (
    upkeep_increase >= 0 AND upkeep_increase = trunc(upkeep_increase)
  ),
  CONSTRAINT company_upgrades_bonus_key_nonempty CHECK (btrim(bonus_key) <> ''),
  CONSTRAINT company_upgrades_bonus_nonnegative CHECK (bonus_value >= 0),
  CONSTRAINT company_upgrades_semantics_check CHECK (
    semantics_status = 'source_value_unreconciled'
  ),
  CONSTRAINT company_upgrades_source_object CHECK (
    jsonb_typeof(source_jsonb) = 'object'
  )
);

ALTER TABLE public.company_upgrades_master ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.company_upgrades_master FROM anon, authenticated;

